@using sv_ebfd3f20379941f6add4e41056260c65.Services

<div class="settings-section">
    <h2>Notifications</h2>

    <div class="notification-form">
        <div class="toggle-group">
            <label class="toggle-label">
                <input type="checkbox" @bind="EmailNotifications" class="toggle-input" />
                <span class="toggle-switch"></span>
                <span>Email Notifications</span>
            </label>
        </div>

        <div class="toggle-group">
            <label class="toggle-label">
                <input type="checkbox" @bind="PushNotifications" class="toggle-input" />
                <span class="toggle-switch"></span>
                <span>Push Notifications</span>
            </label>
        </div>

        <div class="toggle-group">
            <label class="toggle-label">
                <input type="checkbox" @bind="WeeklyDigest" class="toggle-input" />
                <span class="toggle-switch"></span>
                <span>Weekly Digest</span>
            </label>
        </div>

        <div class="muted-channels">
            <h3>Muted Channels</h3>
            @if (AvailableChannels.Count > 0)
            {
                @foreach (var channel in AvailableChannels)
                {
                    <label class="channel-item">
                        <input type="checkbox"
                               checked="@MutedChannels.Contains(channel)"
                               @onchange="e => ToggleChannel(channel, (bool)(e.Value ?? false))" />
                        <span>@channel</span>
                    </label>
                }
            }
            else
            {
                <p class="text-muted">No channels available.</p>
            }
        </div>

        <div class="form-actions">
            <button class="btn btn-primary" @onclick="SaveAsync" disabled="@IsSaving">
                @(IsSaving ? "Saving..." : "Save Preferences")
            </button>
        </div>

        @if (ShowSuccessMessage)
        {
            <div class="toast toast-success">Preferences saved successfully!</div>
        }
    </div>
</div>

@code {
    [Parameter] public NotificationPrefs? Prefs { get; set; }
    [Parameter] public List<string> AvailableChannels { get; set; } = new();
    [Parameter] public EventCallback<NotificationPrefs> OnSave { get; set; }

    private bool EmailNotifications { get; set; }
    private bool PushNotifications { get; set; }
    private bool WeeklyDigest { get; set; }
    private List<string> MutedChannels { get; set; } = new();
    private bool IsSaving { get; set; }
    private bool ShowSuccessMessage { get; set; }

    protected override void OnParametersSet()
    {
        if (Prefs is not null && !_initialized)
        {
            EmailNotifications = Prefs.EmailNotifications;
            PushNotifications = Prefs.PushNotifications;
            WeeklyDigest = Prefs.WeeklyDigest;
            MutedChannels = new List<string>(Prefs.MutedChannels);
            _initialized = true;
        }
    }

    private bool _initialized;

    private void ToggleChannel(string channel, bool muted)
    {
        if (muted && !MutedChannels.Contains(channel))
            MutedChannels.Add(channel);
        else if (!muted)
            MutedChannels.Remove(channel);
    }

    private async Task SaveAsync()
    {
        IsSaving = true;
        var updated = new NotificationPrefs(EmailNotifications, PushNotifications, WeeklyDigest, new List<string>(MutedChannels));
        await OnSave.InvokeAsync(updated);
        IsSaving = false;
        ShowSuccessMessage = true;
        _ = HideSuccessAfterDelay();
    }

    private async Task HideSuccessAfterDelay()
    {
        await Task.Delay(3000);
        ShowSuccessMessage = false;
        StateHasChanged();
    }
}
"}

{"path": "/tmp/sv-ebfd3f20379941f6add4e41056260c65/Components/Pages/Settings/SecuritySection.razor", "file_text": "@namespace sv_ebfd3f20379941f6add4e41056260c65.Components.Pages.Settings
@using sv_ebfd3f20379941f6add4e41056260c65.Services

<div class="settings-section">
    <h2>Security</h2>

    <!-- Change Password Panel -->
    <div class="expandable-panel">
        <button class="panel-header" @onclick="() => PasswordPanelExpanded = !PasswordPanelExpanded">
            <span>Change Password</span>
            <span class="panel-toggle">@(PasswordPanelExpanded ? "▼" : "▶")</span>
        </button>
        @if (PasswordPanelExpanded)
        {
            <div class="panel-body">
                <div class="form-group">
                    <label for="currentPassword">Current Password</label>
                    <input id="currentPassword" type="password" @bind="CurrentPassword" class="form-control" />
                </div>
                <div class="form-group">
                    <label for="newPassword">New Password</label>
                    <input id="newPassword" type="password" @bind="NewPassword" class="form-control" />
                </div>
                <div class="form-group">
                    <label for="confirmPassword">Confirm Password</label>
                    <input id="confirmPassword" type="password" @bind="ConfirmPassword" class="form-control" />
                </div>

                @if (!string.IsNullOrEmpty(PasswordError))
                {
                    <div class="alert alert-error">@PasswordError</div>
                }
                @if (PasswordSuccess)
                {
                    <div class="alert alert-success">Password updated successfully!</div>
                }

                <button class="btn btn-primary" @onclick="UpdatePasswordAsync" disabled="@IsUpdatingPassword">
                    @(IsUpdatingPassword ? "Updating..." : "Update Password")
                </button>
            </div>
        }
    </div>

    <!-- Two-Factor Authentication -->
    <div class="security-group">
        <h3>Two-Factor Authentication</h3>
        <div class="twofa-status">
            <span class="status-indicator @(TwoFactorEnabled ? "status-enabled" : "status-disabled")"></span>
            <span>@(TwoFactorEnabled ? "Enabled" : "Disabled")</span>
            <label class="toggle-label">
                <input type="checkbox" @bind="TwoFactorEnabled" class="toggle-input" />
                <span class="toggle-switch"></span>
            </label>
        </div>
        @if (Settings?.LastPasswordChange is not null)
        {
            <p class="text-muted">Last password change: @Settings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
        }
    </div>

    <!-- Active Sessions -->
    <div class="security-group">
        <h3>Active Sessions</h3>
        @if (Settings?.Sessions is { Count: > 0 })
        {
            <table class="sessions-table">
                <thead>
                    <tr>
                        <th>Device</th>
                        <th>Location</th>
                        <th>Last Active</th>
                        <th>Actions</th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var session in Settings.Sessions)
                    {
                        <tr>
                            <td>@session.Device</td>
                            <td>@session.Location</td>
                            <td>@session.LastActive.ToString("g")</td>
                            <td>
                                @if (session.Id != CurrentSessionId)
                                {
                                    <button class="btn btn-danger btn-sm"
                                            @onclick="() => ShowRevokeConfirmation(session)">
                                        Revoke
                                    </button>
                                }
                                else
                                {
                                    <span class="badge badge-current">Current</span>
                                }
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        }
        else
        {
            <p class="text-muted">No active sessions found.</p>
        }
    </div>

    <!-- Revoke Confirmation Dialog -->
    @if (SessionToRevoke is not null)
    {
        <div class="modal-overlay" @onclick="CancelRevoke">
            <div class="modal-dialog" @onclick:stopPropagation="true">
                <h3>Revoke Session</h3>
                <p>Are you sure you want to revoke the session on <strong>@SessionToRevoke.Device</strong> from <strong>@SessionToRevoke.Location</strong>?</p>
                <div class="modal-actions">
                    <button class="btn btn-danger" @onclick="ConfirmRevokeAsync" disabled="@IsRevoking">
                        @(IsRevoking ? "Revoking..." : "Revoke")
                    </button>
                    <button class="btn btn-secondary" @onclick="CancelRevoke" disabled="@IsRevoking">Cancel</button>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Parameter] public SecuritySettings? Settings { get; set; }
    [Parameter] public string CurrentSessionId { get; set; } = "";
    [Parameter] public EventCallback<(string currentPassword, string newPassword)> OnChangePassword { get; set; }
    [Parameter] public EventCallback<string> OnRevokeSession { get; set; }

    private bool PasswordPanelExpanded { get; set; }
    private string CurrentPassword { get; set; } = "";
    private string NewPassword { get; set; } = "";
    private string ConfirmPassword { get; set; } = "";
    private string? PasswordError { get; set; }
    private bool PasswordSuccess { get; set; }
    private bool IsUpdatingPassword { get; set; }
    private bool TwoFactorEnabled { get; set; }
    private ActiveSession? SessionToRevoke { get; set; }
    private bool IsRevoking { get; set; }

    protected override void OnParametersSet()
    {
        if (Settings is not null)
        {
            TwoFactorEnabled = Settings.TwoFactorEnabled;
        }
    }

    private async Task UpdatePasswordAsync()
    {
        PasswordError = null;
        PasswordSuccess = false;

        if (string.IsNullOrWhiteSpace(CurrentPassword))
        {
            PasswordError = "Current password is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(NewPassword))
        {
            PasswordError = "New password is required.";
            return;
        }
        if (NewPassword != ConfirmPassword)
        {
            PasswordError = "New password and confirmation do not match.";
            return;
        }

        IsUpdatingPassword = true;
        try
        {
            await OnChangePassword.InvokeAsync((CurrentPassword, NewPassword));
            PasswordSuccess = true;
            CurrentPassword = "";
            NewPassword = "";
            ConfirmPassword = "";
        }
        catch (Exception ex)
        {
            PasswordError = ex.Message;
        }
        finally
        {
            IsUpdatingPassword = false;
        }
    }

    private void ShowRevokeConfirmation(ActiveSession session)
    {
        SessionToRevoke = session;
    }

    private void CancelRevoke()
    {
        SessionToRevoke = null;
    }

    private async Task ConfirmRevokeAsync()
    {
        if (SessionToRevoke is null) return;
        IsRevoking = true;
        await OnRevokeSession.InvokeAsync(SessionToRevoke.Id);
        IsRevoking = false;
        SessionToRevoke = null;
    }
}
"}

{"path": "/tmp/sv-ebfd3f20379941f6add4e41056260c65/Components/Pages/Settings/AppearanceSection.razor", "file_text": "@namespace sv_ebfd3f20379941f6add4e41056260c65.Components.Pages.Settings
@using sv_ebfd3f20379941f6add4e41056260c65.Services

<div class="settings-section">
    <h2>Appearance</h2>

    <div class="appearance-form">
        <!-- Theme Selector -->
        <div class="form-group">
            <h3>Theme</h3>
            <div class="radio-group">
                @foreach (var theme in Themes)
                {
                    <label class="radio-label">
                        <input type="radio" name="theme" value="@theme"
                               checked="@(SelectedTheme == theme)"
                               @onchange="() => SelectedTheme = theme" />
                        <span>@theme</span>
                    </label>
                }
            </div>
        </div>

        <!-- Font Size Selector -->
        <div class="form-group">
            <h3>Font Size</h3>
            <div class="radio-group">
                @foreach (var size in FontSizes)
                {
                    <label class="radio-label">
                        <input type="radio" name="fontSize" value="@size"
                               checked="@(SelectedFontSize == size)"
                               @onchange="() => SelectedFontSize = size" />
                        <span>@size</span>
                    </label>
                }
            </div>
        </div>

        <!-- Language Dropdown -->
        <div class="form-group">
            <label for="language">Language</label>
            <select id="language" @bind="SelectedLanguage" class="form-control">
                @foreach (var lang in Languages)
                {
                    <option value="@lang">@lang</option>
                }
            </select>
        </div>

        <!-- Compact Mode Toggle -->
        <div class="toggle-group">
            <label class="toggle-label">
                <input type="checkbox" @bind="CompactMode" class="toggle-input" />
                <span class="toggle-switch"></span>
                <span>Compact Mode</span>
            </label>
        </div>

        <!-- Live Preview -->
        <div class="live-preview @GetPreviewClasses()">
            <h4>Preview</h4>
            <p class="preview-text">This is how your content will look with the selected settings.</p>
            <div class="preview-card">
                <span class="preview-title">Sample Card</span>
                <span class="preview-body">Lorem ipsum dolor sit amet, consectetur adipiscing elit.</span>
            </div>
        </div>

        <div class="form-actions">
            <button class="btn btn-primary" @onclick="SaveAsync" disabled="@IsSaving">
                @(IsSaving ? "Saving..." : "Save")
            </button>
        </div>

        @if (ShowSuccessMessage)
        {
            <div class="toast toast-success">Appearance settings saved!</div>
        }
    </div>
</div>

@code {
    [Parameter] public AppearanceSettings? Settings { get; set; }
    [Parameter] public EventCallback<AppearanceSettings> OnSave { get; set; }

    private static readonly string[] Themes = ["Light", "Dark", "System"];
    private static readonly string[] FontSizes = ["Small", "Medium", "Large"];
    private static readonly string[] Languages = ["English", "Spanish", "French", "German", "Japanese", "Chinese"];

    private string SelectedTheme { get; set; } = "System";
    private string SelectedFontSize { get; set; } = "Medium";
    private string SelectedLanguage { get; set; } = "English";
    private bool CompactMode { get; set; }
    private bool IsSaving { get; set; }
    private bool ShowSuccessMessage { get; set; }

    protected override void OnParametersSet()
    {
        if (Settings is not null && !_initialized)
        {
            SelectedTheme = Settings.Theme;
            SelectedFontSize = Settings.FontSize;
            SelectedLanguage = Settings.Language;
            CompactMode = Settings.CompactMode;
            _initialized = true;
        }
    }

    private bool _initialized;

    private string GetPreviewClasses()
    {
        var classes = $"preview-theme-{SelectedTheme.ToLowerInvariant()} preview-font-{SelectedFontSize.ToLowerInvariant()}";
        if (CompactMode) classes += " preview-compact";
        return classes;
    }

    private async Task SaveAsync()
    {
        IsSaving = true;
        var updated = new AppearanceSettings(SelectedTheme, SelectedFontSize, SelectedLanguage, CompactMode);
        await OnSave.InvokeAsync(updated);
        IsSaving = false;
        ShowSuccessMessage = true;
        _ = HideSuccessAfterDelay();
    }

    private async Task HideSuccessAfterDelay()
    {
        await Task.Delay(3000);
        ShowSuccessMessage = false;
        StateHasChanged();
    }
}
"}

