@page "/settings"
@namespace sv_ebfd3f20379941f6add4e41056260c65.Components.Pages.Settings
@using sv_ebfd3f20379941f6add4e41056260c65.Services
@rendermode InteractiveServer
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-layout">
    <SettingsSidebar ActiveSection="@ActiveSection" OnSectionChanged="SetActiveSection" />

    <main class="settings-content">
        @if (IsLoading)
        {
            <div class="loading-indicator">Loading...</div>
        }
        else
        {
            @switch (ActiveSection)
            {
                case "Profile":
                    <ProfileSection Profile="@Profile" OnSave="SaveProfileAsync" />
                    break;
                case "Notifications":
                    <NotificationsSection Prefs="@NotificationPrefs"
                                          AvailableChannels="@AvailableChannels"
                                          OnSave="SaveNotificationPrefsAsync" />
                    break;
                case "Security":
                    <SecuritySection Settings="@Security"
                                     CurrentSessionId="@CurrentSessionId"
                                     OnChangePassword="ChangePasswordAsync"
                                     OnRevokeSession="RevokeSessionAsync" />
                    break;
                case "Appearance":
                    <AppearanceSection Settings="@Appearance" OnSave="SaveAppearanceAsync" />
                    break;
            }
        }
    </main>
</div>

@code {
    private string ActiveSection { get; set; } = "Profile";
    private bool IsLoading { get; set; } = true;

    private UserProfile? Profile { get; set; }
    private NotificationPrefs? NotificationPrefs { get; set; }
    private SecuritySettings? Security { get; set; }
    private AppearanceSettings? Appearance { get; set; }

    // In a real app, these would come from a channels service
    private List<string> AvailableChannels { get; set; } = new() { "General", "Announcements", "Random", "Engineering", "Design" };
    private string CurrentSessionId { get; set; } = "current-session";

    protected override async Task OnInitializedAsync()
    {
        await LoadAllSettingsAsync();
        IsLoading = false;
    }

    private async Task LoadAllSettingsAsync()
    {
        Profile = await SettingsService.GetProfileAsync();
        NotificationPrefs = await SettingsService.GetNotificationPrefsAsync();
        Security = await SettingsService.GetSecuritySettingsAsync();
        Appearance = await SettingsService.GetAppearanceAsync();
    }

    private void SetActiveSection(string section)
    {
        ActiveSection = section;
    }

    private async Task SaveProfileAsync(UserProfile profile)
    {
        await SettingsService.SaveProfileAsync(profile);
        Profile = profile;
    }

    private async Task SaveNotificationPrefsAsync(NotificationPrefs prefs)
    {
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        NotificationPrefs = prefs;
    }

    private async Task ChangePasswordAsync((string currentPassword, string newPassword) args)
    {
        await SettingsService.ChangePasswordAsync(args.currentPassword, args.newPassword);
    }

    private async Task RevokeSessionAsync(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
        Security = await SettingsService.GetSecuritySettingsAsync();
    }

    private async Task SaveAppearanceAsync(AppearanceSettings settings)
    {
        await SettingsService.SaveAppearanceAsync(settings);
        Appearance = settings;
    }
}

