toolArgs.file_text:
.settings-layout {
    display: flex;
    min-height: calc(100vh - 4rem);
    gap: 0;
}

/* Sidebar */
.settings-sidebar {
    width: 240px;
    background: var(--sidebar-bg, #f8f9fa);
    border-right: 1px solid var(--border-color, #e0e0e0);
    padding: 1.5rem 0;
    flex-shrink: 0;
}

.settings-nav {
    list-style: none;
    padding: 0;
    margin: 0;
}

.settings-nav-item {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.75rem 1.5rem;
    cursor: pointer;
    transition: background-color 0.15s, border-left-color 0.15s;
    border-left: 3px solid transparent;
    color: var(--text-color, #495057);
}

.settings-nav-item:hover {
    background: var(--hover-bg, #e9ecef);
}

.settings-nav-item.active {
    background: var(--active-bg, #e3f2fd);
    border-left-color: var(--primary-color, #1976d2);
    color: var(--primary-color, #1976d2);
    font-weight: 600;
}

.settings-nav-icon {
    font-size: 1.2rem;
}

/* Content Area */
.settings-content {
    flex: 1;
    padding: 2rem;
    max-width: 800px;
}

.settings-section h2 {
    margin-bottom: 1.5rem;
    font-size: 1.5rem;
    font-weight: 600;
    color: var(--heading-color, #212529);
}

.settings-section h3 {
    margin: 1.25rem 0 0.75rem;
    font-size: 1.1rem;
    font-weight: 500;
}

/* Form Controls */
.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.375rem;
    font-weight: 500;
    color: var(--label-color, #495057);
}

.form-control {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid var(--border-color, #ced4da);
    border-radius: 6px;
    font-size: 0.95rem;
    transition: border-color 0.15s;
    background: var(--input-bg, #fff);
    color: var(--text-color, #212529);
}

.form-control:focus {
    outline: none;
    border-color: var(--primary-color, #1976d2);
    box-shadow: 0 0 0 3px rgba(25, 118, 210, 0.1);
}

textarea.form-control {
    resize: vertical;
}

/* Buttons */
.btn {
    padding: 0.5rem 1.25rem;
    border: none;
    border-radius: 6px;
    font-size: 0.9rem;
    font-weight: 500;
    cursor: pointer;
    transition: background-color 0.15s, opacity 0.15s;
}

.btn:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-primary {
    background: var(--primary-color, #1976d2);
    color: #fff;
}

.btn-primary:hover:not(:disabled) {
    background: var(--primary-hover, #1565c0);
}

.btn-secondary {
    background: var(--secondary-bg, #6c757d);
    color: #fff;
}

.btn-secondary:hover:not(:disabled) {
    background: var(--secondary-hover, #5a6268);
}

.btn-danger {
    background: var(--danger-color, #dc3545);
    color: #fff;
}

.btn-danger:hover:not(:disabled) {
    background: var(--danger-hover, #c82333);
}

.btn-sm {
    padding: 0.25rem 0.75rem;
    font-size: 0.8rem;
}

.form-actions {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.5rem;
}

/* Toggle Switches */
.toggle-group {
    margin-bottom: 1rem;
}

.toggle-label {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    cursor: pointer;
    user-select: none;
}

.toggle-input {
    width: 18px;
    height: 18px;
    accent-color: var(--primary-color, #1976d2);
}

/* Toast/Messages */
.toast {
    margin-top: 1rem;
    padding: 0.75rem 1rem;
    border-radius: 6px;
    font-size: 0.9rem;
    animation: slideIn 0.3s ease;
}

.toast-success {
    background: var(--success-bg, #d4edda);
    color: var(--success-color, #155724);
    border: 1px solid var(--success-border, #c3e6cb);
}

@keyframes slideIn {
    from { opacity: 0; transform: translateY(-10px); }
    to { opacity: 1; transform: translateY(0); }
}

/* Alert */
.alert {
    padding: 0.75rem 1rem;
    border-radius: 6px;
    margin-bottom: 1rem;
    font-size: 0.9rem;
}

.alert-error {
    background: #f8d7da;
    color: #721c24;
    border: 1px solid #f5c6cb;
}

.alert-success {
    background: #d4edda;
    color: #155724;
    border: 1px solid #c3e6cb;
}

/* Avatar Preview */
.avatar-preview {
    margin-bottom: 1.5rem;
    text-align: center;
}

.avatar-image {
    width: 96px;
    height: 96px;
    border-radius: 50%;
    object-fit: cover;
    border: 3px solid var(--border-color, #e0e0e0);
    margin-bottom: 0.5rem;
}

.avatar-url-display {
    font-size: 0.8rem;
    color: var(--text-muted, #6c757d);
    word-break: break-all;
}

/* Muted Channels */
.muted-channels {
    margin-top: 1.5rem;
    padding-top: 1rem;
    border-top: 1px solid var(--border-color, #e0e0e0);
}

.channel-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.375rem 0;
    cursor: pointer;
}

/* Expandable Panel */
.expandable-panel {
    border: 1px solid var(--border-color, #e0e0e0);
    border-radius: 8px;
    margin-bottom: 1.5rem;
    overflow: hidden;
}

.panel-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    width: 100%;
    padding: 1rem 1.25rem;
    background: var(--panel-header-bg, #f8f9fa);
    border: none;
    cursor: pointer;
    font-size: 1rem;
    font-weight: 500;
    color: var(--text-color, #212529);
}

.panel-header:hover {
    background: var(--hover-bg, #e9ecef);
}

.panel-body {
    padding: 1.25rem;
    border-top: 1px solid var(--border-color, #e0e0e0);
}

/* Security */
.security-group {
    margin-top: 1.5rem;
    padding-top: 1rem;
    border-top: 1px solid var(--border-color, #e0e0e0);
}

.twofa-status {
    display: flex;
    align-items: center;
    gap: 0.75rem;
}

.status-indicator {
    width: 10px;
    height: 10px;
    border-radius: 50%;
}

.status-enabled {
    background: #28a745;
}

.status-disabled {
    background: #dc3545;
}

.sessions-table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 1rem;
}

.sessions-table th,
.sessions-table td {
    padding: 0.75rem;
    text-align: left;
    border-bottom: 1px solid var(--border-color, #e0e0e0);
}

.sessions-table th {
    font-weight: 600;
    background: var(--table-header-bg, #f8f9fa);
}

.badge {
    padding: 0.25rem 0.5rem;
    border-radius: 4px;
    font-size: 0.75rem;
    font-weight: 500;
}

.badge-current {
    background: var(--success-bg, #d4edda);
    color: var(--success-color, #155724);
}

/* Modal */
.modal-overlay {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: rgba(0, 0, 0, 0.5);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
}

.modal-dialog {
    background: #fff;
    padding: 2rem;
    border-radius: 12px;
    max-width: 420px;
    width: 90%;
    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.3);
}

.modal-dialog h3 {
    margin-top: 0;
}

.modal-actions {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.5rem;
